const constant = require('../lib/constant');

/**
 * getString key
 * setString key value
 * getStringBatch key [key ...] [key array] [key set]
 * getStringBatchWithVer key [key ...] [key array] [key set]
 * setStringBatch key value [key value ...] [obj] [map]
 * getStringWithVer key
 * setStringEx key value ver expire
 * delString key
 */
module.exports = (common) => {
  const operations = {
    * getString(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return null;
      }
      return yield common.getString(key, forceMaster);
    },

    * setString(key, value) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined) {
        return false;
      }
      return yield common.setString(key, value);
    },

    * getStringBatch(...keys) {
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      keys = common.getFieldToArray(keys);
      /* istanbul ignore if */
      if (keys === null) {
        return [];
      }
      if (keys.length > 1) {
        return yield common.getBatch(keys, false, true, forceMaster);
      }
      return [ yield operations.getString(keys[0], forceMaster) ];
    },

    * getStringBatchWithVer(...keys) {
      let forceMaster;
      if (keys.length > 1 && keys[keys.length - 1] === constant.CONSTANT.FORCEMASTER) {
        forceMaster = constant.CONSTANT.FORCEMASTER;
        keys = keys.slice(0, keys.length - 1);
      }
      keys = common.getFieldToArray(keys);
      /* istanbul ignore if */
      if (keys === null) {
        return [];
      }
      if (keys.length > 1) {
        return yield common.getBatch(keys, true, true, forceMaster);
      }
      return [ yield this.getStringWithVer(keys[0], forceMaster) ];
    },

    * setStringBatch(...kvs) {
      const obj = common.getFieldToObj(kvs);
      if (obj === null) {
        return false;
      }
      return yield common.setBatchObj(obj);
    },

    * getStringWithVer(key, forceMaster) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return null;
      }
      return yield common.getStringWithVer(key, forceMaster);
    },

    // eslint-disable-next-line no-unused-vars
    * setStringEx(key, value, ver, expire) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key) || value === null || value === undefined || ver === null || ver === undefined) {
        return false;
      }
      return yield common.setStringEx(...arguments);
    },

    * delString(key) {
      /* istanbul ignore if */
      if (common.isNotStrOrEmpty(key)) {
        return false;
      }
      return yield common.delString(key);
    },

  };
  return operations;
};
